import CoreGraphics
import CoreText
import Foundation
import Vision
@testable import MadoInfrastructure

/// One line of body text rendered with the system UI font, black on white, as the #693 minimum-strength sample.
/// Samples are rendered at test time (see TestAssets/README.md, "Redaction text samples"): the committed fixtures
/// are generated by a fontless Python script, and system text depends on the host's fonts.
struct RedactionTextSample: CustomStringConvertible {
    static let english = "Transfer 4,280.50 to account 6217 0033 1985 by Friday"
    static let chinese = "请在周五之前把报销单交给财务部的王老师"
    static let points: [CGFloat] = [13, 15, 17]
    static let scales: [Int] = [1, 2]

    /// Every combination the brief names: 13/15/17 pt, @1x and @2x, English and Chinese.
    static let all: [RedactionTextSample] = [english, chinese].flatMap { text in
        points.flatMap { point in scales.map { RedactionTextSample(text: text, point: point, scale: $0) } }
    }

    let text: String
    let point: CGFloat
    let scale: Int
    /// The rendered sample and the rectangle, in image pixels with a top-left origin, that holds the whole line.
    let image: CGImage
    let lineRect: CGRect

    var description: String { "\(text == Self.english ? "en" : "zh") \(Int(point))pt @\(scale)x" }

    init(text: String, point: CGFloat, scale: Int) {
        self.text = text; self.point = point; self.scale = scale
        let font = CTFontCreateUIFontForLanguage(.system, point, nil)!
        let black = CGColor(srgbRed: 0, green: 0, blue: 0, alpha: 1)
        let string = NSAttributedString(string: text, attributes: [
            NSAttributedString.Key(kCTFontAttributeName as String): font,
            NSAttributedString.Key(kCTForegroundColorAttributeName as String): black,
        ])
        let line = CTLineCreateWithAttributedString(string)
        var ascent: CGFloat = 0, descent: CGFloat = 0, leading: CGFloat = 0
        let width = CGFloat(CTLineGetTypographicBounds(line, &ascent, &descent, &leading))
        let pad: CGFloat = 12
        let s = CGFloat(scale)
        let pixelWidth = Int(((width + 2 * pad) * s).rounded(.up))
        let pixelHeight = Int(((ascent + descent + 2 * pad) * s).rounded(.up))
        let context = CGContext(data: nil, width: pixelWidth, height: pixelHeight, bitsPerComponent: 8, bytesPerRow: 0,
                                space: CGColorSpace(name: CGColorSpace.sRGB)!,
                                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
        context.setFillColor(CGColor(srgbRed: 1, green: 1, blue: 1, alpha: 1))
        context.fill(CGRect(x: 0, y: 0, width: pixelWidth, height: pixelHeight))
        context.scaleBy(x: s, y: s)
        context.setShouldAntialias(true)
        context.setShouldSmoothFonts(true)
        context.textPosition = CGPoint(x: pad, y: pad + descent)
        CTLineDraw(line, context)
        image = context.makeImage()!
        lineRect = CGRect(x: pad * s, y: pad * s, width: width * s, height: (ascent + descent) * s)
    }

    /// The line after a mosaic of exactly `cell` pixels over `lineRect`.
    func mosaic(cell: Int) throws -> CGImage {
        try RedactionRenderer.pixelate(image, rect: lineRect, cell: cell)
    }
}

/// Apple Vision `.accurate` text recognition with Chinese and English, the recogniser decision 5.3 measures against.
enum RedactionVision {
    static func recognise(_ image: CGImage) throws -> [String] {
        let request = VNRecognizeTextRequest()
        request.recognitionLevel = .accurate
        request.recognitionLanguages = ["zh-Hans", "en-US"]
        request.usesLanguageCorrection = true
        try VNImageRequestHandler(cgImage: image, options: [:]).perform([request])
        return (request.results ?? []).compactMap { $0.topCandidates(1).first?.string }
    }

    /// Letters, digits and CJK characters, case-folded; spaces and punctuation are not counted.
    static func characters(_ text: String) -> Set<Character> {
        Set(text.lowercased().filter { $0.isLetter || $0.isNumber })
    }

    /// The characters of `original` that appear anywhere in what Vision read.
    static func matched(_ recognised: [String], original: String) -> Set<Character> {
        characters(recognised.joined(separator: " ")).intersection(characters(original))
    }
}
